{
  "issues": [
    "背景中提及“丈夫早年病故”，属于给定身份外的亲属与婚姻信息，违反硬性要求。",
    "背景中“独自拉扯廖荣与廖贞”隐含配偶缺失，仍与给定户籍成员关系冲突。",
    "知识字段中“物价行情”涉及钱物，违反不写钱数的要求。"
  ],
  "profile": {
    "personality": {
      "traits": ["沉静", "细致", "耐性"],
      "values": ["学问敬惜", "本分持家"],
      "flaws": ["寡言少断"]
    },
    "voice": {
      "register": "平实书面语，略带学馆用词",
      "accent": "东学坊一带的河岸口音，尾音轻软",
      "habits": ["说话前先抿唇", "抄录时习惯默念字句"],
      "samples": [
        "这页字骨还软，再晾一晾才好收册。",
        "荣儿，灯芯剪短些，莫熏了纸。",
        "贞儿别趴在案边，墨会沾袖口。"
      ]
    },
    "background": "生在河岸，自小随人认字，后来在东学坊学馆领了抄录的活计。多年替馆中誊写蒙书与字样板，也顺带照看灯祠的纸灯。每日送廖荣与廖贞去学馆旁听，自己伏案抄写，傍晚收纸归家。日子清简，与两个孩子相依过活。",
    "currentConcern": "学馆新到一批字样板，须在入冬前抄完，又怕耽误接廖贞下学。",
    "goals": [
      "把新字样板按时誊清，不出错漏",
      "让廖荣和廖贞都能认全常用字"
    ],
    "fears": ["自己病倒，两个孩子无人照看"],
    "knowledge": {
      "unknown": [
        "学馆以外各坊的营生门道",
        "灯祠老旧线路的修缮法子"
      ]
    },
    "relationships": [
      {
        "with": "npc_pop_bs_014_2",
        "relation": "子女",
        "note": "廖荣十岁，已能帮着裁纸理墨，性子急，常被提醒慢些。"
      },
      {
        "with": "npc_pop_bs_014_3",
        "relation": "子女",
        "note": "廖贞五岁，爱跟着去灯祠看灯，怕黑，须牵着走。"
      }
    ],
    "visibleFeature": "右手中指有常年握笔留下的薄茧，袖口常沾着洗不净的淡墨痕。"
  }
}
